static List<String> creationOrder(Map<String, List<String>> needs) {
    List<String> order = new ArrayList<>();
    Set<String> done = new HashSet<>();
    for (String name : needs.keySet()) visit(name, needs, done, new LinkedHashSet<>(), order);
    return order;
}

static void visit(String name, Map<String, List<String>> needs, Set<String> done,
                  LinkedHashSet<String> path, List<String> order) {
    if (done.contains(name)) return;                       // finished earlier: not a loop
    if (path.contains(name)) {                             // back at a name we are still inside
        List<String> loop = new ArrayList<>(path);
        loop = loop.subList(loop.indexOf(name), loop.size());
        throw new IllegalStateException("cycle: " + String.join(" -> ", loop) + " -> " + name);
    }
    path.add(name);
    for (String dep : needs.getOrDefault(name, List.of())) visit(dep, needs, done, path, order);
    path.remove(name);
    done.add(name);
    order.add(name);                                       // after everything it needs
}
